export const DATA_13: ReadingTest[] = [
  { id: "rd-016", num: 16, title: "Đề 016", timeMin: 60, parts: [
    { title: "The Diverse Geography and Rich History of Africa", paragraphs: ["Africa is the second-largest continent on Earth, and its landscapes vary far more than most outsiders assume. In the north, the Sahara Desert spreads across an area nearly as large as the United States, its dunes shifting slowly under a relentless sun. Farther south, the Congo Basin holds one of the largest rainforests on the planet, home to gorillas, forest elephants, and thousands of plant species found nowhere else. Grassy savannas stretch across much of the east and south, supporting the migrations of wildebeest, zebra, and antelope that draw visitors from around the world. Snow even caps the peak of Mount Kilimanjaro, despite its location near the equator, a detail that surprises many travelers.", "Running through this varied terrain are some of the world's most significant rivers and geological formations. The Nile, widely regarded as the longest river on Earth, flows northward for more than six thousand kilometers before reaching the Mediterranean Sea, sustaining agriculture in Egypt and Sudan along the way. To the east, the Great Rift Valley cuts a dramatic scar across the land, formed by tectonic plates slowly pulling apart over millions of years. This same geological process created a chain of lakes and volcanoes that continues to reshape the region today. Such features have long influenced where people settled and how early societies developed.", "Long before European explorers arrived, Africa was home to sophisticated and highly organized societies. Ancient Egypt, centered along the fertile banks of the Nile, built monumental structures and developed one of the earliest writing systems in human history. Further south, the kingdom of Kush rivaled Egypt in power for centuries, while the Mali Empire later grew wealthy through control of gold and salt trade routes across the Sahara. The city of Timbuktu became a center of learning, attracting scholars and merchants from distant regions. These achievements challenge the outdated notion, once common in Western textbooks, that African history began only with colonization.", "The late nineteenth century brought a dramatic and painful shift. European powers divided the continent among themselves during what became known as the Scramble for Africa, drawing borders that ignored existing ethnic and cultural boundaries. Colonial rule extracted resources and labor for the benefit of distant capitals, often at tremendous human cost. Independence movements gained momentum through the mid-twentieth century, and by the 1960s, dozens of new nations had emerged. Many of these countries still grapple with the political and economic legacies of that earlier division.", "Today, Africa's cultural diversity is as striking as its physical geography. More than two thousand distinct languages are spoken across the continent, reflecting an extraordinary range of traditions, music, and belief systems. Nigeria alone contains over two hundred fifty ethnic groups, each with its own customs and history. This diversity, paired with the continent's dramatic landscapes and layered past, makes Africa far more complex than the single, simplified image often presented elsewhere."], questions: [{ q: "According to the passage, what is surprising about Mount Kilimanjaro?", options: ["It sits in the middle of the vast Sahara Desert", "Its peak formed when tectonic plates slowly pulled apart", "Frost still covers its peak despite the warm equatorial climate", "It supports migrations of wildlife across nearby grasslands"], answer: 2 }, { q: "The word \"monumental\" in paragraph 3 is closest in meaning to _______.", options: ["grand", "ancient", "religious", "temporary"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["European colonization permanently damaged every African nation's economy", "The Sahara Desert shaped nearly all of Africa's early history", "Modern Africa struggles mainly because of its harsh climate", "Africa's landscapes and past are more varied than commonly assumed"], answer: 3 }, { q: "According to the passage, which of the following is true about the Nile River?", options: ["It begins in Sudan and ends deep inside Egypt's deserts", "It travels north for over six thousand kilometers to the sea", "It was formed by the same forces as the Rift Valley", "It supports the migrations of wildlife across the eastern grasslands"], answer: 1 }, { q: "The word \"These\" in paragraph 3 refers to _______.", options: ["Egypt, Kush, and Mali", "Scholars and merchants", "Distant trading regions", "Old Western textbooks"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned about the Mali Empire and Timbuktu?", options: ["Control of gold and salt trade routes across the Sahara", "Recognition as a major center of scholarly learning", "Regular visits from scholars and merchants from distant areas", "Command of a large and powerful standing army"], answer: 3 }, { q: "According to the passage, what happened during the Scramble for Africa?", options: ["New borders were drawn without regard for existing ethnic groups", "Independence arrived immediately after the new borders were drawn", "Colonial rule mainly benefited local African merchants and traders", "The Scramble for Africa began in the mid-twentieth century"], answer: 0 }, { q: "The word \"grapple\" in paragraph 4 is closest in meaning to _______.", options: ["celebrate", "struggle", "profit", "forget"], answer: 1 }, { q: "What can be inferred from the passage about earlier Western accounts of African history?", options: ["Western textbooks eventually corrected their entire portrayal of ancient Africa", "Africa's early achievements caused European powers to colonize it", "Older Western accounts largely overlooked Africa's early achievements", "European powers divided Africa into new colonies"], answer: 2 }, { q: "What is the author's main purpose in writing this passage?", options: ["To criticize modern African governments for ongoing political issues", "To correct a narrow view of Africa's geography and history", "To argue that colonization alone caused Africa's modern problems", "To warn that Africa's diversity threatens its political stability"], answer: 1 }] },
    { title: "Alice in Wonderland and the Evolution of the Escape Room Experience", paragraphs: ["Few children's books have proven as durable, or as strange, as Lewis Carroll's tale of a girl who tumbles down a rabbit hole into a world where logic bends and identity shifts without warning. Readers have long been drawn less to the plot than to its texture: a landscape where doors talk, cakes alter one's size, and a grinning cat vanishes while leaving only its smile behind. It is this coherent nonsense, rules that feel internally consistent even as they defy ordinary sense, that later designers of physical puzzle experiences would come to value most.", "Escape rooms first appeared in the early 2010s, growing out of point-and-click computer games in which players clicked through scenes to uncover hidden objects and solve sequential puzzles. Entrepreneurs in Japan and Hungary independently began adapting this format into physical spaces, locking small groups inside a themed room and challenging them to find clues and escape before a timer expired. What began as a niche hobby expanded within a decade into a global industry spanning thousands of venues.", "Wonderland's influence on this expanding industry became apparent almost as soon as designers began searching for thematic material with built-in tension between order and disorder. A room can shrink the player's sense of scale through forced perspective, echoing the shrinking and growing that Alice herself endures; an ordinary door can conceal an entirely different chamber behind it, mirroring the story's collapsing boundaries between spaces. Designers borrowed not merely costumes but the underlying logic of a world that punishes literal thinking and rewards lateral leaps.", "Several structural techniques, in fact, migrated directly from the book's riddles into contemporary puzzle design. The Mad Hatter's unanswerable question, framed as a real riddle yet given no true solution, anticipated a device now common in escape rooms: a clue that appears to demand one kind of reasoning while actually requiring another entirely. Cryptic wordplay of the sort Carroll delighted in, puns folded into innocent dialogue, likewise reappears in ciphers that reward players who read text for double meanings rather than surface content.", "Industry figures suggest revenue from escape rooms may have tripled between the mid-2010s and the early 2020s, though estimates vary depending on how loosely the category is defined. Some analysts attribute this growth chiefly to social media, arguing that photogenic sets encourage visitors to share their experience online; others contend that the deeper appeal lies in the same craving for structured strangeness that has kept Carroll's novel in print for over a century. Neither explanation alone fully accounts for the industry's expansion.", "Beyond entertainment, educators and corporate trainers have adopted escape-room formats for their capacity to sharpen collaborative reasoning under time pressure. Teams that succeed tend to be those willing to voice an unlikely interpretation rather than defending an initial, confident guess, precisely the disposition Alice must adopt to survive Wonderland's shifting rules. Whether this transferable skill persists once participants leave the room remains a question researchers have only begun to examine.", "As the format matures, some designers have begun returning explicitly to literary sources rather than treating them as decorative backdrop, constructing rooms that attempt to replicate a book's internal logic rather than merely borrowing its imagery. Whether this closer literary fidelity will define the medium's next phase, or prove a passing trend among a handful of studios, is not yet possible to say."], questions: [{ q: "What is the main idea of the passage?", options: ["Escape rooms borrowed only Alice's costumes and visual decorations", "Wonderland's internally consistent illogic shaped how escape rooms are designed", "Video games, not literature, remain the sole inspiration for escape rooms", "Escape rooms became popular mainly because Carroll's novel is well known"], answer: 1 }, { q: "According to the passage, how did escape rooms originate?", options: ["They developed from computer games built around clicking and searching", "They were invented in the United States before spreading abroad", "They replaced point-and-click games entirely within a single decade", "They began as a marketing tool for children's book publishers"], answer: 0 }, { q: "The word \"coherent\" in paragraph 1 is closest in meaning to _______.", options: ["amusing", "childish", "consistent", "ancient"], answer: 2 }, { q: "According to the passage, how do escape room designers echo Alice's experience in Wonderland?", options: ["Every escape room must feature a hidden door somewhere", "Costumes alone are enough to recreate Wonderland's tension", "Designers avoid rooms that punish overly literal thinking", "Forced perspective can mimic the size changes Alice experiences"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a technique borrowed from the book's riddles?", options: ["A riddle that seems to require one type of reasoning", "Wordplay containing puns hidden within ordinary dialogue", "Physical locks that require solving a mathematical equation", "Ciphers that reward players who notice double meanings"], answer: 2 }, { q: "The word \"this\" in paragraph 6 refers to _______.", options: ["voicing unlikely interpretations", "defending confident guesses", "designing themed puzzle rooms", "measuring team performance scores"], answer: 0 }, { q: "According to the passage, what is true about the escape room industry's revenue growth?", options: ["Social media is universally agreed to be its main cause of growth", "Its growth rate has been precisely measured by every analyst", "Its expansion has slowed sharply since the early 2010s began", "Estimates of its revenue growth vary by how the category is defined"], answer: 3 }, { q: "The word \"disposition\" in paragraph 6 is closest in meaning to _______.", options: ["ability", "schedule", "tendency", "reputation"], answer: 2 }, { q: "What can be inferred from the passage about the reasoning skills built in escape rooms?", options: ["Corporate training programs have proven escape rooms improve teamwork permanently", "Reasoning skills gained there may not last", "Escape rooms cause employees to distrust their confident guesses", "Researchers have already confirmed escape rooms build lasting reasoning skills"], answer: 1 }, { q: "What is the author's main purpose in writing this passage?", options: ["To explore how a literary work has shaped a modern industry", "To dismiss escape rooms as a shallow, unoriginal form of entertainment", "To prove that Carroll intentionally designed puzzles for future games", "To warn readers that escape rooms exploit young children's imaginations"], answer: 0 }] },
    { title: "Artificial Intelligence in the Modern Business Landscape", paragraphs: ["The most consequential effect of artificial intelligence on business may not be the efficiency gains that dominate headlines, but a quieter redistribution of who, or what, actually makes decisions. Executives once relied on intuition sharpened by years of experience; increasingly, that judgment is supplemented, and in some cases superseded, by systems trained on historical data. This shift did not arrive suddenly. It accumulated gradually, department by department, until few companies could say precisely when a human stopped being the final check on a given choice.", "Automation's more visible face appears in customer-facing tools and logistics. Chatbots now field a substantial share of routine service inquiries, while forecasting algorithms adjust inventory levels before regional managers have finished their morning coffee. Whether this substitution meaningfully reduces the need for entry-level staff remains disputed among labor economists, some of whom argue that displaced workers simply shift toward tasks the software cannot yet perform, while others contend that the net effect, once adjustment costs are included, still favors reduction. Neither camp treats the question as settled.", "Less visible, though arguably more significant, is the migration of predictive analytics into terrain once reserved for senior leadership. Pricing strategy, hiring shortlists, and even merger evaluations now pass through models before they reach a boardroom table, and in some firms the model's output functions less as an input to deliberation than as its practical conclusion. Mid-level managers, armed with dashboards rather than years of institutional memory, increasingly make calls that would once have required escalation.", "This migration of authority carries a cost that only becomes visible when something goes wrong. Many of the systems in question are opaque by design, optimized for predictive accuracy rather than interpretability. While such models can weigh variables far beyond what any manager could track unaided, their recommendations often resist straightforward explanation, which complicates the already difficult task of assigning responsibility once an outcome proves costly. A decision nobody can fully explain is, in a legal and reputational sense, a decision nobody fully owns.", "Regulators across different jurisdictions have responded with markedly different instruments, from mandatory disclosure requirements to outright restrictions on certain automated decisions. Some observers expect these divergent approaches to converge over time, as multinational firms lobby for a single compliance standard rather than dozens of incompatible ones; others suspect that national interests, particularly around data sovereignty, will keep the regulatory landscape fragmented indefinitely. The pattern so far offers support for both predictions in roughly equal measure.", "A further consequence, easy to overlook amid debates over jobs and regulation, concerns which companies can even participate in this transformation. Building or fine-tuning advanced models requires computing infrastructure that only a handful of firms currently supply at scale, and smaller companies wishing to adopt similar tools must typically rent that capacity from the same few providers. What looks, from a distance, like a wave of independent corporate innovation may in practice be consolidating around a narrow set of infrastructural gatekeepers.", "Whether these overlapping shifts ultimately concentrate strategic power among a small number of firms, or instead diffuse decision-making capacity more broadly across the economy, is not yet possible to determine with confidence, and the answer will likely depend on regulatory choices that have not yet been made."], questions: [{ q: "What is the main idea of the passage?", options: ["AI mainly reduces the need for entry-level customer service staff", "AI's deeper business impact lies in shifting decision-making, not automating routine tasks", "AI primarily helps executives make decisions with greater personal confidence", "AI adoption will eventually make regulatory oversight completely unnecessary"], answer: 1 }, { q: "According to the passage, why do labor economists disagree about whether AI reduces the need for entry-level jobs?", options: ["They dispute whether workers shift tasks or losses persist after costs", "They disagree because automation always eliminates jobs permanently and irreversibly", "Entry-level workers caused algorithms to be adopted more slowly than expected", "Chatbots currently handle a very large share of daily routine customer inquiries"], answer: 0 }, { q: "The word \"opaque\" in paragraph 4 is closest in meaning to _______.", options: ["biased", "flexible", "unclear", "obvious"], answer: 2 }, { q: "According to the passage, what does the current evidence suggest about the future of AI regulation across countries?", options: ["Multinational firms have already achieved one single global compliance standard", "Regulatory fragmentation has caused multinational firms to abandon international operations", "Regulators have used mandatory disclosure rules and outright restrictions", "The available pattern lends roughly equal support to convergence and fragmentation"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a factor in smaller firms' reliance on major AI infrastructure providers?", options: ["Building advanced models requires computing infrastructure at a large scale", "Only a handful of firms supply this infrastructure at scale", "Government subsidies specifically fund smaller firms' AI adoption efforts", "Smaller firms must rent computing capacity from those same providers"], answer: 2 }, { q: "The phrase \"This\" in paragraph 4 refers to _______.", options: ["Predictive analytics' expanded role", "Boardroom table decisions", "Institutional memory", "Merger evaluations"], answer: 0 }, { q: "According to the passage, why does assigning responsibility become difficult when an AI-informed business decision goes wrong?", options: ["Managers deliberately hide the model's reasoning in order to avoid blame", "The models are optimized for accuracy, so their reasoning resists clear explanation", "Difficulty assigning blame caused companies to make their models more opaque", "Some models can weigh variables beyond what a manager could track"], answer: 1 }, { q: "The word \"fragmented\" in paragraph 5 is closest in meaning to _______.", options: ["regulated", "delayed", "unified", "divided"], answer: 3 }, { q: "What can be inferred about the relationship between infrastructure concentration and corporate innovation, based on the passage?", options: ["Innovation that seems independent may depend on a shared provider", "Smaller firms will eventually build their own competing infrastructure", "Independent innovation has caused infrastructure providers to lower prices", "A handful of firms currently supply advanced computing infrastructure at scale"], answer: 0 }, { q: "What is the author's overall stance toward AI's growing role in business decision-making?", options: ["Alarmed specifically about the ongoing job losses within customer service roles", "Cautiously uncertain whether power will concentrate or simply diffuse", "Confident that regulation will soon resolve all concerns", "Strongly opposed to any further adoption of AI in business"], answer: 1 }] },
    { title: "The Transformation of Education through Artificial Intelligence", paragraphs: ["Not only has artificial intelligence begun to alter what students study, but it may also be quietly redefining what counts as mastery in the first place. A generation of software capable of drafting essays, solving equations, and generating code on request has forced educators to confront a question that predates computing by centuries yet feels suddenly urgent: whether the point of instruction was ever the artifact a student produces, or the thinking that producing it was meant to cultivate.", "Adaptive learning platforms represent the technology's most established classroom presence, continuously adjusting the difficulty, pacing, and sequence of material according to a given learner's demonstrated performance rather than a fixed curriculum designed for an average student. Early adopters report measurable gains on standardized assessments, though whether those gains reflect deeper conceptual comprehension or merely a closer alignment between the instruction delivered and the test ultimately administered is a question the available data cannot yet resolve. Proponents tend to treat the two as functionally equivalent; skeptics do not.", "More contentious still is the growing use of generative tools for drafting and problem-solving, a practice that has unsettled long-standing assumptions about authorship in student work. Some instructors have responded by redesigning assignments around in-class, unassisted composition, effectively conceding that take-home writing can no longer verify what a student individually knows. Others have moved in the opposite direction, treating fluency with these tools as a skill worth teaching directly rather than a threat to be policed, on the theory that graduates will use such tools professionally regardless of what any syllabus prohibits.", "Underlying both responses is a disagreement that rarely surfaces explicitly: whether the tools mainly displace lower-order tasks, freeing attention for the conceptual work that supposedly matters more, or whether the two are entangled closely enough that outsourcing the former quietly erodes the latter. Longitudinal evidence remains thin, and the studies that do exist disagree not merely in their conclusions but in what they treat as a valid measure of learning to begin with.", "Institutions have also begun deploying these systems for tasks once performed exclusively by instructors, including preliminary grading, plagiarism screening, and, in a smaller but growing number of cases, elements of academic advising previously handled by trained staff. Administrators frequently justify this expansion by pointing to constrained budgets and expanding enrollment, arguing that automation merely reallocates scarce instructor time toward higher-value interactions. Faculty responses vary considerably across departments and disciplines, and where a given department ultimately lands often reflects prior attitudes toward standardized assessment more than any settled judgment about the technology itself.", "A further complication, seldom addressed in enthusiastic accounts of classroom innovation, involves unequal access to these very tools across districts, regions, and income levels. Wealthier institutions can license sophisticated platforms and train faculty in their use, while under-resourced schools may adopt cheaper, less carefully vetted alternatives or forgo the technology altogether, a disparity that could widen existing achievement gaps even as it narrows others, depending on which effects ultimately dominate.", "Whether artificial intelligence will, on balance, deepen educational inequality or help offset it, whether it will sharpen critical thinking or merely simulate its outward signs, and whether today's contested compromises will look prescient or naive in another decade are questions this generation of educators appears no closer to resolving than when the tools first arrived, notwithstanding the confidence with which partisans on every side continue to speak."], questions: [{ q: "What is the main idea of the passage?", options: ["AI mainly helps students finish assignments faster with less mental effort", "AI forces a reexamination of what learning artifacts are meant to demonstrate", "AI will soon replace instructors across most levels of formal education", "AI adoption has already resolved long-standing debates about student assessment"], answer: 1 }, { q: "According to the passage, what remains unresolved about adaptive learning platforms' reported gains?", options: ["Whether measured gains reflect real comprehension or closer test alignment is unresolved", "Adaptive platforms have been proven to increase comprehension more than any other method", "Standardized test scores caused adaptive platforms to be removed from most classrooms", "Early adopters uniformly reject standardized measures as invalid for judging outcomes"], answer: 0 }, { q: "The word \"contentious\" in paragraph 3 is closest in meaning to _______.", options: ["outdated", "affordable", "disputed", "temporary"], answer: 2 }, { q: "According to the passage, how have instructors differently responded to generative tools?", options: ["All instructors have banned generative tools from every classroom assignment", "Instructors agree unanimously that in-class writing best verifies student knowledge", "Generative tools have eliminated the need for any writing instruction at all", "Some redesign assignments around unassisted writing, while others teach the tools directly"], answer: 3 }, { q: "According to the passage, which of the following is NOT part of the underlying disagreement over generative tools' effect on learning?", options: ["Whether tools mainly displace lower-order tasks and free attention for concepts", "Whether university enrollment has grown faster than instructor hiring nationwide", "Whether outsourcing every routine task always erodes conceptual skills involved", "Whether displaced attention has been proven to improve overall learning outcomes"], answer: 1 }, { q: "The phrase \"the two\" in paragraph 2 refers to _______.", options: ["standardized measures", "early adopters", "available data", "comprehension and test alignment"], answer: 3 }, { q: "According to the passage, what does unequal access to AI tools mean for achievement gaps?", options: ["Under-resourced schools have already closed the gap by adopting cheaper tools", "Wealthier institutions have stopped licensing advanced platforms due to rising costs", "The disparity could widen or narrow achievement gaps depending on which effects dominate", "Unequal access has been shown to have no measurable effect on outcomes"], answer: 2 }, { q: "The word \"prescient\" in paragraph 7 is closest in meaning to _______.", options: ["accurate", "insightful", "traditional", "present"], answer: 1 }, { q: "What can be inferred from the passage about why departments differ in their AI policies?", options: ["Departments may adopt AI policies based on existing habits rather than new evidence", "All departments will eventually adopt identical policies once evidence becomes clear", "Faculty attitudes toward AI are caused directly by their department's budget size", "Institutions have deployed automation for tasks such as grading and advising"], answer: 0 }, { q: "What is the author's main purpose in writing this passage?", options: ["To convince readers that AI will inevitably worsen educational inequality", "To argue that generative tools should be banned from all classrooms", "To present unresolved tensions in AI's educational impact neutrally", "To celebrate adaptive learning platforms as the field's most important advance"], answer: 2 }] },
  ] },
  { id: "rd-180", num: 180, title: "Đề 180", timeMin: 60, parts: [
    { title: "The Role of Genetics in Choosing a Partner", paragraphs: ["For many years, people have believed that falling in love is mostly about shared interests, personality, and simple luck. However, a growing number of scientists suggest that our bodies may also send out biological signals that shape who we find attractive. One area of interest involves a group of genes known as the major histocompatibility complex, or MHC, which helps the immune system recognize and fight off harmful invaders . Researchers have discovered that these genes may influence body scent in ways that people cannot consciously detect, yet the smell still appears to guide romantic preference. This idea, once considered unusual, has now become a serious topic of study in the field of human attraction.", "In a well-known experiment carried out in Switzerland, male volunteers wore the same cotton T-shirt for two nights without using soap, cologne, or deodorant. Afterward, female participants were asked to smell the shirts and rate how pleasant each scent was. Most women, without knowing anything about the men who wore the shirts, tended to prefer the scent of men whose MHC genes were noticeably different from their own. Interestingly, when the same women were later given birth control pills to take, their scent preferences shifted, and several began favoring men with genes more similar to theirs. This unexpected shift suggested that hormones, not just personal taste, may quietly steer whom we find appealing.", "Scientists offer a straightforward explanation for this pattern: choosing a partner with different immune genes could give future children a wider range of natural defenses against disease. A child who inherits two different sets of MHC genes may be better equipped to recognize a broader variety of infections than a child whose parents share nearly identical genes. Separate research involving twins raised apart has added further support to this theory , showing that some romantic preferences appear even without any shared environment or upbringing. Even so, the researchers were careful to note that biology alone rarely, if ever, determines who a person falls in love with.", "Despite these findings, most experts agree that genetics plays only a supporting role, not the leading one, in human attraction. Culture, upbringing, shared values, and simple daily familiarity still appear to matter far more than smell or hidden biology. Some critics of the T-shirt studies also point out that the sample sizes were often small, and that later attempts to repeat the results did not always succeed. For this reason, many scientists now describe genetic attraction as one thread among many, rather than a hidden master switch controlling romance.", "Taken together, this research does not replace the everyday explanations people give for falling in love. Instead, it adds a quiet biological layer beneath the more familiar social one. As more studies are carried out, scientists hope to learn exactly how much influence, however small, our genes truly have on the partners we eventually choose."], questions: [{ q: "According to the passage, how long did the men wear the T-shirt during the experiment, and what did they avoid using?", options: ["Two weeks, without changing their daily clothing.", "One night, without soap, cologne, or deodorant.", "Two nights, while wearing strong cologne only.", "Two nights, without soap, cologne, or deodorant."], answer: 3 }, { q: "What is the main idea of the passage?", options: ["MHC genes are the main cause of romantic attraction.", "Genetic signals subtly support, but do not control, attraction.", "Birth control pills permanently reverse a person's genetic preferences.", "Cultural factors have completely replaced biology in attraction."], answer: 1 }, { q: "Why might children benefit from parents with different MHC genes, according to the passage?", options: ["They may inherit their parents' identical scent preferences.", "They may develop unusually strong physical strength overall.", "They may inherit a wider range of immune defenses.", "They may avoid essentially all hereditary illnesses entirely."], answer: 2 }, { q: "The word \"steer\" in paragraph 2 is closest in meaning to _______.", options: ["smell", "guide", "stir", "force"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a factor affecting attraction?", options: ["The importance of shared personal values", "A person's yearly household income level", "The influence of a person's cultural background", "Sudden changes in hormone levels during studies"], answer: 1 }, { q: "What happened when the women in the study began taking birth control pills?", options: ["Every participant stopped noticing any scent differences immediately.", "Their hormone levels returned to pre-teenage childhood patterns.", "Some began favoring men with more similar genes.", "Their preference for different genes grew noticeably stronger."], answer: 2 }, { q: "The phrase \"this theory\" in paragraph 3 refers to _______.", options: ["twins raised apart", "the diverse-gene explanation", "the birth control effect", "natural defenses only"], answer: 1 }, { q: "The word \"invaders\" in paragraph 1 is closest in meaning to _______.", options: ["scents", "enemies", "invitees", "germs"], answer: 3 }, { q: "What can be inferred from the passage about the reliability of the T-shirt study's findings?", options: ["The Swiss study focused only on twin siblings.", "Small sample sizes caused unexpectedly stronger overall results.", "Its findings have since been completely disproven scientifically.", "Its results have not always been replicated successfully."], answer: 3 }, { q: "What is the author's overall attitude toward the idea that genetics influences attraction?", options: ["Skeptical, doubting the validity of all cited studies.", "Fully convinced that genetics determines romantic partner choice.", "Dismissive, viewing biology as irrelevant to attraction.", "Cautiously open, treating genetics as one contributing factor."], answer: 3 }] },
    { title: "E-Commerce and Economic Development After the Pandemic", paragraphs: ["When national governments began closing non-essential shops in early 2020, few observers expected the shift that would follow. What started as an emergency workaround for shuttered retailers gradually hardened into a lasting change in how goods and services reach consumers. Online marketplaces, once seen mainly as a convenient alternative for busy professionals, suddenly became the primary channel through which millions of households obtained groceries, medicine, and everyday necessities. This abrupt transition, forced rather than chosen, nonetheless revealed consumer habits that many analysts now believe are unlikely to fully reverse.", "Global e-commerce sales, according to several trade organizations, rose by roughly thirty percent within the first eighteen months of the pandemic, though growth rates varied sharply across regions and income groups. Small retailers, many of whom had previously resisted moving online, were often forced to build a digital storefront within weeks rather than years. Some succeeded, occasionally reaching customers far beyond their original neighborhoods; others, lacking the technical skill or capital to compete, closed permanently. Whether this rapid digitization ultimately strengthened or weakened local economies remains a question researchers continue to debate, since the answer appears to depend heavily on local infrastructure.", "Traditional brick-and-mortar retail did not simply vanish, however, despite predictions to the contrary made early in the pandemic. Physical stores, particularly those offering experiences that screens cannot replicate, gradually recovered a portion of the customers they had lost. What emerged instead, in many markets, was a hybrid model in which shoppers research products online yet still prefer to complete certain purchases in person. This blending complicates any simple narrative of digital replacing physical retail entirely, and suggests instead that consumer behavior settled somewhere between the two extremes rather than at either one.", "Beneath these visible shifts in shopping behavior lies a less discussed layer of economic development. Countries that had already invested in digital payment systems and reliable delivery networks before the pandemic were, unsurprisingly, better positioned to absorb the sudden surge in online demand. In several developing economies, mobile payment platforms that had struggled for years to gain widespread adoption saw usage climb sharply once physical alternatives became inconvenient or unavailable. Some economists argue that this crisis-driven adoption may have compressed a decade of digital infrastructure growth into a matter of months, though such claims remain difficult to verify with precision.", "Not every region benefited equally, of course. Rural communities with limited internet access and unreliable postal services frequently found themselves unable to participate meaningfully in the new digital marketplace, even when demand for online shopping existed. This uneven access, often layered on top of existing income inequality, has led some researchers to warn that e-commerce growth risks widening rather than narrowing regional economic gaps unless deliberate policy intervention accompanies it.", "In response, several governments introduced incentives intended to extend broadband access and support small business digitization, while simultaneously tightening regulations around consumer data protection and online fraud. Critics argue that such measures often arrive years after the underlying problems became obvious, and that regulatory frameworks continue to lag behind the pace of technological change. Supporters counter that even delayed intervention is preferable to none, particularly as online commerce becomes further embedded in everyday economic life.", "Whether the pandemic-era surge in e-commerce ultimately represents a temporary disruption or a permanent restructuring of economic activity remains genuinely uncertain. What does seem clear, based on the evidence so far, is that the digital and physical economies are unlikely to separate cleanly again, however the balance between them continues to evolve."], questions: [{ q: "According to the passage, why were some countries better able to handle the surge in online shopping during the pandemic?", options: ["They had already built strong digital payment infrastructure.", "They restricted physical stores earlier than other nations.", "They received emergency loans from international trade organizations.", "They had larger populations than other countries."], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Traditional retail recovered fully and now dominates once again.", "Government regulation was the primary driver of this growth.", "Developing nations fully matched wealthy countries' digital infrastructure.", "E-commerce growth reshaped retail without fully replacing physical stores."], answer: 3 }, { q: "The word \"hardened\" in paragraph 1 is closest in meaning to _______.", options: ["toughened", "solidified", "hindered", "expanded"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a government response to e-commerce growth?", options: ["Direct cash payments issued to online shoppers", "Tighter regulations covering consumer data protection", "New incentives to expand rural broadband access", "Support programs aimed at small business digitization"], answer: 0 }, { q: "What does the passage suggest about the long-term impact of pandemic-driven digital adoption in developing economies?", options: ["It may have sped up years of infrastructure growth.", "It had no measurable effect on payment systems.", "It definitely compressed a decade of growth into months.", "It slowed infrastructure investment in most developing regions."], answer: 0 }, { q: "The phrase \"such claims\" in paragraph 4 refers to _______.", options: ["mobile payment platforms", "the decade-compression argument", "physical alternatives unavailable", "digital payment systems"], answer: 1 }, { q: "Why did some rural communities struggle to benefit from e-commerce growth, according to the passage?", options: ["They received lower government subsidies than urban areas.", "They lacked reliable internet access and postal services.", "They lacked interest in online shopping generally.", "They faced stricter regulations on digital payments."], answer: 1 }, { q: "The word \"compressed\" in paragraph 4 is closest in meaning to _______.", options: ["crushed", "compensated", "delayed", "condensed"], answer: 3 }, { q: "What can be inferred from the passage about the future relationship between digital and physical retail?", options: ["Global e-commerce sales rose by about thirty percent early on.", "The two are likely to remain intertwined going forward.", "Digital retail will keep growing until physical stores disappear.", "Physical stores caused the rise of online shopping platforms."], answer: 1 }, { q: "What is the author's attitude toward the long-term effects of pandemic-driven e-commerce growth?", options: ["Fully confident that all changes are permanent worldwide.", "Dismissive of any lasting impact on retail.", "Strongly critical of governments' regulatory responses.", "Cautiously uncertain, acknowledging both permanence and unresolved questions."], answer: 3 }] },
    { title: "Genetic Research into Human Longevity", paragraphs: ["Although longevity has often been attributed to lifestyle choices such as diet and exercise, a growing body of genetic research suggests that inherited variation may account for a meaningful share of the difference between those who die in their sixties and those who remain vigorous past a hundred. Twin studies, which compare identical and fraternal siblings raised in similar environments, have repeatedly estimated that genetics explains somewhere between twenty and thirty percent of variation in lifespan — a figure that, while modest, is far from negligible when multiplied across an entire population.", "Much of the recent excitement centers on a single gene, FOXO3, first linked to unusually long life in a study of Japanese men living on the island of Okinawa, a region long celebrated for its unusually high concentration of centenarians. Carriers of a particular variant of this gene appeared, across several independent population studies conducted afterward in Europe and North America, to enjoy not merely a longer lifespan but a compressed period of illness near the end of it — meaning that disease and disability, when they did arrive, tended to arrive later and progress more briefly than in non-carriers.", "That FOXO3 alone determines who reaches extreme old age would, however, be a considerable overstatement of what the evidence actually supports. The gene appears to interact with dozens of other genetic variants, environmental exposures, and even chance cellular events in ways researchers have only begun to map. Some scientists suspect that FOXO3's true contribution lies not in adding years directly but in improving the body's resilience to stress — a subtler and harder-to-measure effect that may explain why its influence shows up more reliably in population statistics than in any single individual's medical history.", "A separate line of inquiry has focused on telomeres, the protective caps at the ends of chromosomes that shorten slightly with each cell division. Because shortened telomeres have been correlated with age-related disease in numerous studies, some researchers proposed that telomere length might serve as a biological clock capable of predicting remaining lifespan. Subsequent research has complicated this tidy picture considerably: telomere length varies enormously even among people of identical chronological age, and attempts to extend life by artificially lengthening telomeres in laboratory animals have produced inconsistent, occasionally even harmful, results, undermining the notion that telomeres are a simple countdown mechanism.", "Interestingly, the same Okinawan population that first drew attention to FOXO3 also shares an environment markedly different from that of most industrialized nations — a traditional diet low in calories relative to activity level, strong social integration among the elderly, and continuous physical labor well into old age. This overlap has made it exceptionally difficult for researchers to disentangle genetic advantage from environmental circumstance, since a population selected partly for its unusual genetics also happens to live in unusually favorable conditions for longevity.", "Epigenetics — the study of chemical modifications that switch genes on or off without altering the underlying DNA sequence — has further complicated any straightforward genetic account of aging. These modifications, which can be influenced by diet, stress, and even a parent's own experiences before conception, appear capable of accelerating or delaying age-related decline independently of which gene variants a person happens to carry. Researchers now increasingly describe longevity not as a fixed genetic inheritance but as an ongoing negotiation between fixed sequence and changeable expression.", "Taken together, these findings suggest that no single gene, however promising, is likely to explain extreme longevity on its own. What genetic research has offered instead is a partial map of resilience mechanisms — one that, when combined with favorable environment and considerable luck, may help explain why some individuals thrive well beyond the age most people can expect to reach."], questions: [{ q: "According to the passage, what complicates researchers' ability to credit FOXO3 alone for Okinawan longevity?", options: ["FOXO3 carriers in Okinawa show shorter lifespans overall.", "The gene has never been found outside Okinawa.", "The population also shares unusually favorable lifestyle conditions.", "Telomere length in the population remains unusually short."], answer: 2 }, { q: "What is the main idea of the passage?", options: ["FOXO3 alone fully explains why some people live longest.", "Telomere length reliably predicts every individual's exact remaining lifespan.", "Environmental factors have been proven irrelevant to human longevity.", "Genetic longevity research reveals resilience factors, not a simple cause."], answer: 3 }, { q: "What does the passage suggest FOXO3's true contribution to longevity might be?", options: ["It definitively adds extra years directly to lifespan.", "It primarily prevents telomeres from shortening over time.", "It may improve resilience rather than directly add years.", "It guarantees a compressed period of illness for everyone."], answer: 2 }, { q: "According to the passage, what happened when researchers attempted to lengthen telomeres artificially in laboratory animals?", options: ["Results consistently extended lifespan without any side effects.", "Results were inconsistent and sometimes even harmful.", "The experiments were abandoned before producing any results.", "Telomere length increased but chronological age stayed identical."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a factor influencing longevity?", options: ["Telomere transplantation performed between identical twins", "Epigenetic effects linked to a parent's experiences", "Traditional diet and strong social integration", "Heritability estimates derived from twin studies"], answer: 0 }, { q: "The word \"disentangle\" in paragraph 5 is closest in meaning to _______.", options: ["combine", "separate", "entangle", "destroy"], answer: 1 }, { q: "The word \"resilience\" in paragraph 3 is closest in meaning to _______.", options: ["flexibility", "invincibility", "hardiness", "residence"], answer: 2 }, { q: "The phrase \"This overlap\" in paragraph 5 refers to _______.", options: ["the FOXO3 gene variant", "genetic and environmental advantage together", "traditional low-calorie diet only", "continuous physical labor alone"], answer: 1 }, { q: "What can be inferred from the passage about the reliability of telomere length as a predictor of lifespan?", options: ["FOXO3 carriers show a compressed period of late-life illness.", "Shorter telomeres are caused by age-related disease onset.", "It is far less reliable than early researchers assumed.", "It reliably predicts lifespan once other factors are excluded."], answer: 2 }, { q: "What is the author's attitude toward the idea that a single gene could fully explain human longevity?", options: ["Fully persuaded that FOXO3 alone explains extreme longevity.", "Mildly critical only of twin-study research methods.", "Dismissive of any genetic contribution to human lifespan.", "Skeptical, viewing longevity as multiply determined and complex."], answer: 3 }] },
    { title: "Rethinking the Science of Body Language", paragraphs: ["Few claims about human communication have spread as widely, or been distorted as thoroughly, as the assertion that the overwhelming majority of meaning in a conversation comes not from words but from body language. Traced back to a set of narrow laboratory experiments conducted in the late 1960s — studies that measured how strongly facial expression and tone influenced listeners' judgments of a speaker's feelings on a single, isolated word — this figure has since been stretched far beyond what the original research ever claimed, applied indiscriminately to job interviews, first dates, and courtroom testimony alike.", "What the original studies actually demonstrated was considerably narrower: when the emotional content of a spoken word conflicted with the speaker's tone and facial expression, listeners tended to trust the nonverbal signal more than the word itself. Extending this finding to ordinary conversation, in which words and body language rarely contradict one another so starkly, requires an inferential leap the original researchers themselves never endorsed. Nevertheless, corporate training programs and popular psychology books continued, for decades, to cite the figure as though it applied to communication in general.", "More recent research into deception detection has proven similarly humbling for anyone hoping that body language offers a reliable shortcut to the truth. Trained investigators, when tested under controlled conditions, generally perform little better than chance at distinguishing truthful statements from lies based on posture, gesture, or eye contact alone — a finding that undercuts decades of interrogation training built around supposed nonverbal 'tells.' Some researchers now argue that confident belief in one's own lie-detection ability may itself increase the likelihood of wrongly accusing an innocent, nervous person, since nervousness and dishonesty produce overlapping physical signals.", "Microexpressions — extremely brief facial movements, lasting a fraction of a second, that some researchers argue reveal concealed emotion — have attracted particular attention since being popularized in the early 2000s. Whether these fleeting expressions can be reliably read outside laboratory conditions remains genuinely contested; while some studies suggest trained observers can identify them slightly above chance level, other researchers argue that real-world noise, cultural variation, and the sheer speed of the movements make consistent field application doubtful at best, and that any operational use in security or legal settings would demand far stronger evidence than currently exists.", "Cultural variation complicates the picture still further. [1] Gestures considered warm and encouraging in one society may register as intrusive or even offensive in another, and the physical distance people consider comfortable during conversation shifts noticeably across regions. [2] Even something as apparently universal as eye contact carries different social weight depending on context — read in some settings as a sign of confidence and honesty, and in others as a sign of disrespect toward an elder or authority figure. [3] Researchers caution against treating any single nonverbal signal as a fixed, universal code. [4]", "None of this implies that body language carries no communicative value whatsoever; rather, the accumulating evidence suggests its influence is real but considerably more context-dependent, and considerably less quantifiable, than the popular narrative allows. A raised eyebrow may indeed shift how a listener interprets a sentence, but whether it does so, and how strongly, appears to depend heavily on the relationship between speaker and listener, the surrounding words, and the situation — variables that resist the kind of tidy percentage figure that made the original claim so appealing to repeat.", "Taken as a whole, the research suggests that body language matters, but not in the sweeping, precisely quantified way often claimed. What remains most defensible is a considerably more modest position: nonverbal signals shape communication meaningfully, yet almost always in combination with, rather than instead of, the words that accompany them."], questions: [{ q: "What is the main idea of the passage?", options: ["Body language matters, but far less absolutely than popularly claimed.", "Nonverbal signals carry no real communicative value whatsoever.", "Cultural differences make all nonverbal signals entirely meaningless.", "Body language conveys nearly all meaning in any conversation."], answer: 0 }, { q: "According to the passage, how does the popular claim about nonverbal communication relate to the original 1960s research?", options: ["It extends a narrow finding far beyond its original scope.", "It applies only to conflicting words and tone, as intended.", "It was first proposed by corporate training programs themselves.", "It accurately summarizes what the original researchers concluded."], answer: 0 }, { q: "What does the passage suggest is a risk of confident belief in one's own lie-detection skill?", options: ["It may increase the chance of wrongly accusing innocent people.", "It always guarantees more accurate detection of dishonest people.", "It reduces reliance on posture and gesture during interrogation.", "It has been proven to eliminate nervousness in suspects."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a factor complicating reliable interpretation of body language?", options: ["Cultural differences in gesture and eye contact", "The relationship between speaker and listener", "The speaker's level of formal education", "Real-world background noise affecting microexpression accuracy"], answer: 2 }, { q: "The word \"indiscriminately\" in paragraph 1 is closest in meaning to _______.", options: ["carelessly", "indiscreetly", "unselectively", "confidently"], answer: 2 }, { q: "The word \"humbling\" in paragraph 3 is closest in meaning to _______.", options: ["reassuring", "embarrassing", "humorous", "chastening"], answer: 3 }, { q: "The phrase \"None of this\" in paragraph 6 refers to _______.", options: ["the 1960s experiments only", "the eyebrow example alone", "accumulated research limitations overall", "cultural gesture differences only"], answer: 2 }, { q: "What can be inferred from the passage about the reliability of microexpression reading in real-world settings, such as security screening?", options: ["Microexpressions were first popularized in the early 2000s.", "Trained observers can reliably read microexpressions in any setting.", "Current evidence is too limited to justify confident real-world use.", "Real-world noise improves the accuracy of microexpression detection."], answer: 2 }, { q: "What is the author's overall attitude toward popular claims about body language?", options: ["Entirely dismissive of any usefulness in nonverbal communication.", "Fully convinced that body language communicates almost everything.", "Narrowly critical only of 1960s laboratory methodology.", "Skeptical of exaggerated claims, while not dismissing all nonverbal value."], answer: 3 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This variation makes it risky to assume that a gesture perceived as friendly at home will be read the same way abroad.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
  ] },
];
